BEGIN READ ONLY;
SET LOCAL search_path=pg_catalog;
SELECT jsonb_build_object('database',current_database(),'role',current_user,'session_role',session_user,
 'version_num',current_setting('server_version_num'),'transaction_read_only',current_setting('transaction_read_only'),
 'default_transaction_read_only',current_setting('default_transaction_read_only'),
 'project_setting',current_setting('supabase.project_ref',true),
 'ssl',(select ssl from pg_stat_ssl where pid=pg_backend_pid()));
COMMIT;
